import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;

class Completed {

    public int snakesAndLadders(int[][] board) {

        int n = board.length;
        int target = n * n;
        int[] destination = new int[target + 1];
        Arrays.fill(destination, -1);

        int label = 1;
        boolean leftToRight = true;

        for (int row = n - 1; row >= 0; row--) {
            if (leftToRight) {
                for (int col = 0; col < n; col++) {
                    if (board[row][col] != -1) {
                        destination[label] = board[row][col];
                    }
                    label++;
                }
            } else {
                for (int col = n - 1; col >= 0; col--) {
                    if (board[row][col] != -1) {
                        destination[label] = board[row][col];
                    }
                    label++;
                }
            }
            leftToRight = !leftToRight;
        }

        boolean[] visited = new boolean[target + 1];
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{1, 0});
        visited[1] = true;

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int square = current[0];
            int moves = current[1];

            if (square == target) {
                return moves;
            }

            for (int roll = 1; roll <= 6 && square + roll <= target; roll++) {
                int next = square + roll;
                if (destination[next] != -1) {
                    next = destination[next];
                }

                if (!visited[next]) {
                    visited[next] = true;
                    queue.offer(new int[]{next, moves + 1});
                }
            }
        }

        return -1;
    }
}

